    K.part(`M${P(c([0,0.92]))}L${P(c([0,0.46]))}M${P(c([-4,0.97]))}Q${P(c([-10,0.95]))} ${P(c([-15,0.95]))}M${P(c([4,0.97]))}Q${P(c([10,0.95]))} ${P(c([15,0.95]))}`, "", "fill:none;stroke:var(--plate);stroke-width:1.1;opacity:.7");
