  out.push({ tag: "ellipse", a: { cx: r1(h[0]), cy: r1(h[1]), rx: 9.2, ry: 11.2, class: ghost ? "ghost" : "body", style: ghost ? "" : K.radial("body", add(h, [1.5, -2]), 11) } });
