  const u = [Math.cos(ang * D2R), Math.sin(ang * D2R)], v = [-u[1], u[0]];
  const pts = [[-w / 2, -h / 2], [w / 2, -h / 2], [w / 2, h / 2], [-w / 2, h / 2]].map(([x, y]) => add(c, add(mul(u, x), mul(v, y))));
