// soft contact shadow on the floor
const floorShadow = (ctx, cx, y, rx, o = 1, flat = 0.13) => el("ellipse", { cx: r1(cx), cy: r1(y), rx: r1(rx), ry: r1(rx * flat), fill: `url(#fs${ctx.uid})`, style: `opacity:${o}` });
