  const P0 = spec.pelvis;
  // spec.curl: spinal flexion in degrees, spread evenly from pelvis to neck (constant curvature).
  // Positive curls the trunk toward the front (a crunch). The pelvis itself does not move.
  const k = (spec.curl || 0) * D2R;
  const sAt = t => (Math.abs(k) < 1e-4 ? s : n3(a3(m3(s, Math.cos(k * t)), m3(ant, Math.sin(k * t)))));
